steps.script:
var n = tree.root.get_node_or_null("/root/MainMenu/TutorialNudge")
if n == null or not n.visible:
	return "absent"
var b = n.get_node_or_null("Margin/VBox/Footer/DismissNudgeButton")
if b == null:
	return "no dismiss button"
b.pressed.emit()
return "dismissed"

var sc = tree.root.get_node_or_null("/root/MainMenu/ScrollContainer")
var b = tree.root.get_node_or_null("/root/MainMenu/ScrollContainer/MenuContainer/ButtonSection/SecondaryButtonGrid/TutorialButton")
if sc == null or b == null:
	return false
sc.ensure_control_visible(b)
return true

var host = null
for c in tree.root.get_node("/root/Main").get_children():
	if "Controller" in str(c.name):
		host = c
		break
if host == null:
	return "no controller node under Main to parent onto"
var d = AcceptDialog.new()
d.name = "ProbeControllerDialog"
d.min_size = Vector2i(700, 500)
d.exclusive = true
host.add_child(d)
DialogUtils.popup_at_bottom(d)
if d.get_parent() == tree.root or d.get_parent() == tree.root.get_node("/root/Main"):
	return "probe landed at a depth the two-level scan already covered - proves nothing"
return "ok"

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var seen = []
for w in ov._open_game_windows():
	seen.append(str(w.name))
if not seen.has("ProbeControllerDialog"):
	return "a dialog parented below /root/Main is still invisible to the overlay - it sees only %s" % str(seen)
if ov.card_blocker_overlap() > 0.0:
	return "card buried %.0fpx under an open dialog (card %s)" % [ov.card_blocker_overlap(), str(ov.card_rect())]
return "ok"

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var b = ov.get_node("InstructorCard/Margin/VBox/Footer/ExitTutorialButton")
if not b.disabled:
	return "card's Exit Tutorial still looks live under a modal that swallows every click"
return "ok"

var pm = PopupMenu.new()
pm.name = "ProbeDropdown"
pm.add_item("Tactical")
var d = tree.root.get_node("/root/Main").find_child("ProbeControllerDialog", true, false)
if d == null:
	return false
d.get_parent().add_child(pm)
pm.popup(Rect2i(400, 400, 200, 80))
return true

var d = tree.root.get_node("/root/Main").find_child("ProbeControllerDialog", true, false)
if d != null:
	d.queue_free()
return true

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var pm = tree.root.get_node("/root/Main").find_child("ProbeDropdown", true, false)
if pm == null or not pm.visible:
	return "the dropdown closed on its own - this check proves nothing"
var seen = []
for w in ov._open_game_windows():
	seen.append(str(w.name))
if seen.has("ProbeDropdown"):
	return "an open dropdown counts as a modal - the card would dart to the gutter, and its footer grey, whenever a list is opened"
if seen.has("ProbeControllerDialog"):
	return "the freed probe dialog is still being counted"
if ov.card_blocker_overlap() > 0.0:
	return "card overlaps something after the probe dialog closed"
return "ok"

var pm = tree.root.get_node("/root/Main").find_child("ProbeDropdown", true, false)
if pm != null:
	pm.queue_free()
return true
